Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='gatehalves', at=datetime(2026, 10, 3, 0, 0, 0), actor='assistant', title="The merge gate has two halves: --no-live, a function of the tree, and --only-live, which reads the owner's data", body="It has TWO HALVES (2026-10-03): `--no-live` is the tree half, a function of the tree alone, run with the data tree hidden (`SUZATARY_INSTANCE` names nothing), so it runs in a Codespace of this repository (`.devcontainer/`, Nix and the public Cachix, nothing personal); `--only-live` is the live half, the tests that read the owner's data tree (`--test live`, `--test guards`, the `all` modules in its `live_modules`, `web-test.sh`'s live chain), on the box only. `--list` names every step's half, and `app/cli/tests/guards/merge_gate.rs` fails when a test that reads the data tree is outside the live half.", rationale='Decided 2026-10-03.', supersedes=()))